某些CPU架构直接提供了test-and-set指令。如x86与IBM System/360及其后继(包括 z/Architecture)。没有这种机器指令的，需要用read-modify-write或 compare-and-swap指令来实现。

C语言实现：

 #define LOCKED 1

int TestAndSet(int* lockPtr) {
    int oldValue;

    // Start of atomic segment
    // The following statements should be interpreted as pseudocode for
    // illustrative purposes only.
    // Traditional compilation of this code will not guarantee atomicity, the
    // use of shared memory (i.e. not-cached values), protection from compiler
    // optimization, or other required properties.
    oldValue = *lockPtr;
    *lockPtr = LOCKED;
    // End of atomic segment

    return oldValue;
}

volatile int lock = 0;

 void Critical() {
     while (TestAndSet(&lock) == 1);
     critical section // only one process can be in this section at a time
     lock = 0 // release lock when finished with the critical section
 }

一个CAS操作等价于以下c代码的原子实现: 

int cas(long *addr, long old, long new)
{
    /* Executes atomically. */
    if(*addr != old)
        return 0;
    *addr = new;
    return 1;
}

在使用上，通常会记录下某块内存中的旧值，通过对旧值进行一系列的操作后得到新值，然后通过CAS操作将新值与旧值进行交换。如果这块内存的值在这期间内没被修改过，则旧值会与内存中的数据相同，这时CAS操作将会成功执行 使内存中的数据变为新值。如果内存中的值在这期间内被修改过，则一般来说旧值会与内存中的数据不同，这时CAS操作将会失败，新值将不会被写入内存。

ABA问题是无锁结构实现中常见的一种问题，可基本表述为：

进程P1读取了一个数值A

P1被挂起(时间片耗尽、中断等)，进程P2开始执行

P2修改数值A为数值B，然后又修改回A

P1被唤醒，比较后发现数值A没有变化，程序继续执行。

对于P1来说，数值A未发生过改变，但实际上A已经被变化过了，继续使用可能会出现问题。在CAS操作中，由于比较的多是指针，这个问题将会变得更加严重。试想如下情况： top | V 0x0014 | Node A | --> |  Node X | --> …… 有一个栈(先入后出)中有top和节点A，节点A目前位于栈顶top指针指向A。现在有一个进程P1想要pop一个节点，因此按照如下无锁操作进行

pop()
{
  do{
    ptr = top;            // ptr = top = NodeA
    next_ptr = top->next; // next_ptr = NodeX
  } while(CAS(top, ptr, next_ptr) != true);
  return ptr;   
}

而进程P2在执行CAS操作之前打断了P1，并对栈进行了一系列的pop和push操作，使栈变为如下结构： top | V 0x0014 | Node C | --> | Node B | --> |  Node X | --> …… 进程P2首先pop出NodeA，之后又push了两个NodeB和C，由于内存管理机制中广泛使用的内存重用机制，导致NodeC的地址与之前的NodeA一致。

这时P1又开始继续运行，在执行CAS操作时，由于top依旧指向的是NodeA的地址(实际上已经变为NodeC)，因此将top的值修改为了NodeX，这时栈结构如下： top | 0x0014                           V | Node C | --> | Node B | --> |  Node X | --> …… 经过CAS操作后，top指针错误地指向了NodeX而不是NodeB。

下面是GNU Octave模拟洛伦茨吸引子的源代码：

## Lorenz Attractor equations solved by ODE Solve
## x' = sigma*(y-x)
## y' = x*(rho - z) - y
## z' = x*y - beta*z
function dx = lorenzatt(X)
    rho = 28; sigma = 10; beta = 8/3;
    dx = zeros(3,1);
    dx(1) = sigma*(X(2) - X(1));
    dx(2) = X(1)*(rho - X(3)) - X(2);
    dx(3) = X(1)*X(2) - beta*X(3);
    return
end

## Using LSODE to solve the ODE system.
clear all
close all
lsode_options("absolute tolerance",1e-3)
lsode_options("relative tolerance",1e-4)
t = linspace(0,25,1e3); X0 = [0,1,1.05];
[X,T,MSG]=lsode(@lorenzatt,X0,t);
T
MSG
plot3(X(:,1),X(:,2),X(:,3))
view(45,45)

#include <graphics.h>
#include <conio.h>
void main()
{
    double x = 3.051522, y = 1.582542, z = 15.62388, x1, y1, z1;
    double dt = 0.0001;
    int a = 5, b = 15, c = 1;
    int gd=DETECT, gm;
    initgraph(&gd, &gm, "C:\\BORLANDC\\BGI");
    do {
	x1 = x + a*(-x+y)*dt;
	y1 = y + (b*x-y-z*x)*dt;
	z1 = z + (-c*z+x*y)*dt;
	x = x1;	y = y1;	z = z1;
	putpixel((int)(19.3*(y - x*0.292893) + 320),
		 (int)(-11*(z + x*0.292893) + 392), 9);
    } while (!kbhit());
    closegraph();
}

Program Lorenz;
Uses CRT, Graph;
Const
  x: Real = 3.051522;
  y: Real = 1.582542;
  z: Real = 15.62388;
  dt = 0.0001;
  a = 5;
  b = 15;
  c = 1;
Var
  gd, gm: Integer;
  x1, y1, z1: Real;
Begin
  gd:=Detect;
  InitGraph(gd, gm, 'c:\bp\bgi');
  While not KeyPressed Do Begin
      x1 := x + a*(-x+y)*dt;
      y1 := y + (b*x-y-z*x)*dt;
      z1 := z + (-c*z+x*y)*dt;
      x := x1;
      y := y1;
      z := z1;
      PutPixel(Round(19.3*(y - x*0.292893) + 320),
               Round(-11*(z + x*0.292893) + 392), 9);
    End;
    CloseGraph;
    ReadKey;
End.

白银比例和\tfrac{\pi}{8} = 22.5^\circ 的三角函数数值有关：

\textstyle \sin \frac {\pi}{8} = \cos \frac {3\pi}{8} = \frac{1}{2} \sqrt{2 - \sqrt 2}=\sqrt{ \frac{1}{2\delta_s}}

\textstyle \cos \frac {\pi}{8} = \sin \frac {3\pi}{8} = \frac{1}{2} \sqrt{2 + \sqrt{2}}=\sqrt{ \frac{\delta_s}{2}}

\textstyle \tan \frac {\pi}{8} = \cot \frac {3\pi}{8} = \sqrt{2}-1= \frac{1}{\delta_s}

\textstyle \cot \frac {\pi}{8} = \tan \frac {3\pi}{8} = \sqrt{2}+1=\delta_s

边长为a的正八边形面积可以用下式表示：

A = \textstyle 2a^2 \cot \frac{\pi}{8} = 2(1+\sqrt{2})a^2  \approx 4.828427 a^2.

二维的线性微分方程系统可以写成以下的形式：

\begin{align}
\frac{dx}{dt} & = Ax + By \\
\frac{dy}{dt} & = Cx + Dy 
\end{align}

可以整理为矩阵方程式：

\begin{align}
& \frac{d}{dt} \begin{pmatrix}
x \\
y \\
\end{pmatrix} = \begin{pmatrix}
A & B \\
C & D \\
\end{pmatrix}
\begin{pmatrix}
x \\
y \\
\end{pmatrix} \\

& \frac{d\mathbf{x}}{dt} = \mathbf{A}\mathbf{x}.

\end{align}

其中A是2 × 2的系数矩阵，而x = (x, y)是二个自变量组成的座标向量。

此系统可以解析求解，例如积分下式：

\frac{dy}{dx} = \frac{Cx+Dy}{Ax+By}

不过此解是x和y的隐函数，也不容易诠释。

已知底边长和侧边长的等腰梯形则可以确定其大小，包括外接圆半径、高和面积等特性。

已知等腰梯形底边长为a和b、侧边为c，则高h为：

h=\sqrt{c^2-\tfrac{1}{4}{\left( b-a\right) }^2}

有两种主要特性可以使用线性时序逻辑来表达：

安全性（safety）：即某种不良性质 φ 永不出现，G¬&varphi;

活性（liveness）<：即某种良好的性质 ψ 一直保持，GFψ 或 G(&varphi; →Fψ)

谢尔宾斯基地毯的构造与谢尔宾斯基三角形相似，区别仅在于谢尔宾斯基地毯是以正方形而非等边三角形为基础的。将一个实心正方形划分为3 \times 3的9个小正方形，去掉中间的小正方形，再对余下的小正方形重复这一操作便能得到谢尔宾斯基地毯。

谢尔宾斯基地毯可以由以下计算机程序构造：

/** 确定一个特定位置的点是否被填充。

@param x	是被选点的X座标 @param y	是被选点的Y座标 @param width	是谢尔宾斯基地毯被指定的宽度 @param height	是谢尔宾斯基地毯被指定的高度 @return 当被填充，返回1；而未被填充时，返回0

/

int isSierpinskiCarpetPixelFilled(int x,int y,int width,int height) { // 基本情况 if (x<1) { return 0; }

// 通用情况 { /* 若网格被分为9个部分，x,y会被填入部分(x2,y2)的？

/

int x2 = x*3/width; // 一个处在0到2之间的整形 int y2 = y*3/height; // 一个处在0到2之间的整形

if (x2==1 && y2==1) // 若点在中心方块内，其应被填充。 return 1;

/* 偏移x和y，它们应分别落在0..width/3和0..height/3 并适配递归调用

/

x-=x2*width/3; y-=y2*height/3;

}

return isSierpinskiCarpetPixelFilled(x,y,width/3,height/3); }

